(() => {
  const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const state={rootId:'',targets:[],files:[],nodes:[],selectedTarget:'',selectedFile:'',selectedNode:'',result:null,loading:false,error:'',agentRunId:'',verification:null,verificationLoading:false,verificationError:'',verificationCategory:'',verificationStatus:'',verificationQuery:''};
  const scope=()=>state.rootId?{rootId:state.rootId}:{};
  const activeRoot=()=>((BeastStore.get().workspace.roots||[]).find(folder=>folder.id===state.rootId)?.path)||BeastDesktopBridge.workspaceFolderForPath?.(BeastStore.get().editor.activePath)?.root||BeastStore.get().workspace.root;
  const failureLocations=result=>{const text=`${result?.stdout||''}\n${result?.stderr||''}\n${result?.error||''}`;const seen=new Set();const rows=[];const patterns=[/([A-Za-z0-9_./-]+\.(?:py|js|jsx|ts|tsx)):(\d+)(?::\d+)?/g,/File "([^"]+)", line (\d+)/g];for(const pattern of patterns){let match;while((match=pattern.exec(text))&&rows.length<80){const path=String(match[1]||'').replace(/^\.\//,'');const line=Number(match[2]||1);if(!path||path.startsWith('/')||seen.has(`${path}:${line}`))continue;seen.add(`${path}:${line}`);rows.push({path,line});}}return rows;};
  function template(){const root=document.createElement('div');root.className='beast-page beast-testing-page';root.innerHTML=`
    <header class="beast-page-head"><div><h2>Test Explorer</h2><div class="sub">DISCOVERY // FOCUSED EXECUTION // DEBUG HANDOFF // EVIDENCE RECEIPTS</div></div><div class="beast-page-actions"><button class="beast-button secondary" data-test-action="discover">Discover Tests</button><button class="beast-button hot" data-test-action="run">Run Selected</button><button class="beast-button secondary" data-test-action="debug">Debug Selected</button></div></header>
    <section class="beast-card wide"><div class="terminal-chat-controls"><label><span>WORKSPACE FOLDER</span><select data-test-root></select></label><label><span>RUN TARGET</span><select data-test-target></select></label><label><span>PYTEST CASE</span><select data-test-node></select></label><span class="beast-pill" data-test-status>IDLE</span></div></section>
    <section class="terminal-lower-grid"><section class="beast-card terminal-dev-card"><header class="beast-panel-head"><div><h3>Discovered Test Files</h3><span>Click a file to select it; use Run or Debug for focused pytest execution.</span></div><em data-test-file-count>0</em></header><div class="terminal-problems" data-test-files>Discover tests to build this catalog.</div></section><section class="beast-card terminal-console-card"><header class="beast-panel-head"><div><h3>Test Result</h3><span data-test-summary>No execution yet.</span></div><button class="beast-button secondary" data-test-action="open">Open Selected File</button></header><div class="terminal-problems" data-test-failures>No failure locations yet.</div><pre class="terminal-chat-output" data-test-output>Discover a test target and file, then run it here.</pre></section></section>
    <section class="beast-card wide"><header class="beast-panel-head"><div><h3>Execution History</h3><span>Current-session bounded test receipts</span></div></header><div class="terminal-history-list" data-test-history>No test run yet.</div></section>
    <section class="beast-card wide" data-phase5-10-verification-console><header class="beast-panel-head"><div><h3>Agent Verification Console</h3><span>Durable focused tests, package tests, lint, type checks, security, policy, SourcePlan validation, and post-apply proof.</span></div><em data-agent-verification-state>NOT LOADED</em></header>
      <div class="terminal-chat-controls"><label><span>AGENT RUN ID</span><input data-agent-verification-run placeholder="run-..." /></label><label><span>CATEGORY</span><select data-agent-verification-category><option value="">All categories</option><option value="focused_tests">Focused tests</option><option value="package_tests">Package tests</option><option value="lint">Lint</option><option value="type_check">Type check</option><option value="security">Security</option><option value="policy">Policy</option><option value="sourceplan_validation">SourcePlan validation</option><option value="post_apply_verification">Post-apply verification</option></select></label><label><span>STATUS</span><select data-agent-verification-status><option value="">All statuses</option><option>PASSED</option><option>FAILED</option><option>TIMED_OUT</option><option>SKIPPED</option><option>REUSED_WITH_PROOF</option><option>STALE</option><option>BLOCKED</option><option>RUNNING</option></select></label><label><span>SEARCH</span><input data-agent-verification-query placeholder="command, evidence, step..." /></label><button class="beast-button hot" data-test-action="load-agent-verification">Load Verification</button></div>
      <div class="terminal-lower-grid"><section class="beast-card terminal-dev-card"><header class="beast-panel-head"><div><h3>Verification Summary</h3><span>Freshness and promotion relevance remain separate from promotion authority.</span></div></header><div class="terminal-problems" data-agent-verification-summary>Enter a durable AgentRun ID.</div></section><section class="beast-card terminal-console-card"><header class="beast-panel-head"><div><h3>Verification Checks</h3><span data-agent-verification-count>0 checks</span></div></header><div class="terminal-history-list" data-agent-verification-checks>No durable verification evidence loaded.</div></section></div>
    </section>`;return root;}
  function renderer(){const root=template();const history=[];let disposed=false;
    function render(){if(disposed)return;const store=BeastStore.get();const folders=store.workspace.roots||[];const select=root.querySelector('[data-test-root]');const old=select.value;select.innerHTML=folders.map(folder=>`<option value="${esc(folder.id)}">${esc(folder.name)}${folder.primary?' · primary':''}</option>`).join('');if(!state.rootId||!folders.some(folder=>folder.id===state.rootId))state.rootId=folders.find(folder=>folder.primary)?.id||'';select.value=folders.some(folder=>folder.id===old)?old:state.rootId;const targets=root.querySelector('[data-test-target]');targets.innerHTML='<option value="">Select runnable target…</option>'+state.targets.map(item=>`<option value="${esc(item.id)}">${esc(item.label)} · ${esc(item.framework)}</option>`).join('');targets.value=state.selectedTarget;const nodes=root.querySelector('[data-test-node]');const scopedNodes=state.nodes.filter(item=>!state.selectedFile||item.path===state.selectedFile);nodes.innerHTML='<option value="">Entire selected file / suite</option>'+scopedNodes.map(item=>`<option value="${esc(item.id)}">${esc(item.label)} · ${esc(item.path)}</option>`).join('');if(state.selectedNode&&!scopedNodes.some(item=>item.id===state.selectedNode))state.selectedNode='';nodes.value=state.selectedNode;nodes.disabled=state.selectedTarget!=='python:pytest'||!scopedNodes.length;root.querySelector('[data-test-status]').textContent=state.loading?'DISCOVERING':state.error?'ERROR':state.result?.ok?'PASSED':state.result?'FAILED':'IDLE';root.querySelector('[data-test-file-count]').textContent=String(state.files.length);root.querySelector('[data-test-files]').innerHTML=state.files.length?state.files.map(file=>`<button type="button" class="${file.path===state.selectedFile?'active':''}" data-test-file="${esc(file.path)}"><b>${esc(file.path)}</b><small>${file.path===state.selectedFile?'selected for focused run/debug':'pytest / spec file'}</small></button>`).join(''):'No test files discovered.';const result=state.result;root.querySelector('[data-test-summary]').textContent=result?`${result.ok?'Passed':'Failed'} · ${result.file||result.test?.label||''} · ${result.receipt?.id||''}`:state.error||'No execution yet.';const failures=failureLocations(result);root.querySelector('[data-test-failures]').innerHTML=failures.length?failures.map(item=>`<button type="button" class="error" data-test-failure-path="${esc(item.path)}" data-test-failure-line="${item.line}"><b>${esc(item.path)}:${item.line}</b><small>Open failure location</small></button>`).join(''):'No failure locations yet.';root.querySelector('[data-test-output]').textContent=result?`${result.stdout||''}${result.stderr?`\n[stderr]\n${result.stderr}`:''}${result.error?`\n[error]\n${result.error}`:''}`.slice(-60000):'Discover a test target and file, then run it here.';root.querySelector('[data-test-history]').innerHTML=history.length?history.map(item=>`<button type="button" data-test-history-file="${esc(item.file||'')}"><span><b>${esc(item.ok?'PASSED':'FAILED')} · ${esc(item.file||item.test?.label||'test')}</b><small>${esc(item.receipt?.id||'')} · ${new Date(item.at).toLocaleTimeString()}</small></span></button>`).join(''):'No test run yet.';const verification=state.verification;root.querySelector('[data-agent-verification-run]').value=state.agentRunId;root.querySelector('[data-agent-verification-category]').value=state.verificationCategory;root.querySelector('[data-agent-verification-status]').value=state.verificationStatus;root.querySelector('[data-agent-verification-query]').value=state.verificationQuery;root.querySelector('[data-agent-verification-state]').textContent=state.verificationLoading?'LOADING':state.verificationError?'ERROR':verification?.status||'NOT LOADED';const summary=verification?.summary||{};const counts=summary.counts||{};const promotion=verification?.promotion||{};root.querySelector('[data-agent-verification-summary]').innerHTML=verification?`<div><b>${esc(verification.status)}</b><small>${Number(summary.total_checks||0)} total · ${Number(counts.PASSED||0)} passed · ${Number(counts.FAILED||0)} failed · ${Number(counts.REUSED_WITH_PROOF||0)} reused with proof · ${Number(summary.stale_count||0)} stale</small></div><div class="${promotion.verification_ready?'success':'warning'}"><b>${promotion.verification_ready?'VERIFICATION READY':'PROMOTION BLOCKED'}</b><small>${promotion.verification_ready?'No verification blockers remain. Promotion still requires its separate governed boundary.':`${(promotion.blocking_check_ids||[]).length} blocking check(s)`}</small></div>`:esc(state.verificationError||'Enter a durable AgentRun ID.');const checks=verification?.checks||[];root.querySelector('[data-agent-verification-count]').textContent=`${checks.length} checks`;root.querySelector('[data-agent-verification-checks]').innerHTML=checks.length?checks.map(item=>`<button type="button" class="${item.status==='FAILED'||item.status==='TIMED_OUT'||item.status==='BLOCKED'?'error':item.status==='PASSED'||item.status==='REUSED_WITH_PROOF'?'success':''}" data-agent-verification-check="${esc(item.check_id)}"><span><b>${esc(item.status)} · ${esc(item.category)}</b><small>${esc(item.command||item.event_type)}${item.step_id?` · step ${esc(item.step_id)}`:''}</small><small>${esc(item.concise_output||'No concise output')}${item.freshness?` · ${esc(item.freshness)}`:''}</small><small>${item.evidence_digest?`Evidence ${esc(item.evidence_digest)}`:'No evidence digest'}${item.equivalence_proof_digest?` · Equivalence ${esc(item.equivalence_proof_digest)}`:''}</small></span></button>`).join(''):'No durable verification checks match the current filters.';}
    async function discover(){state.loading=true;state.error='';render();try{const data=await window.beastDesktop.workspaceTests(scope());state.targets=data.tests||[];state.files=data.files||[];state.nodes=data.nodes||[];state.selectedTarget=state.targets.find(item=>item.id==='python:pytest')?.id||state.targets[0]?.id||'';state.selectedFile=state.files[0]?.path||'';state.selectedNode=state.nodes.find(item=>item.path===state.selectedFile)?.id||'';BeastStore.addLedger(`Test Explorer discovered ${state.files.length} file(s) · ${state.nodes.length} pytest case(s)`);}catch(error){state.error=String(error.message||error);}finally{state.loading=false;render();}}
    async function run(debug=false){const id=state.selectedTarget;if(!id)throw new Error('Choose a runnable test target.');const selectedNode=state.selectedNode||'';if(debug){if(id!=='python:pytest')throw new Error('Focused debug currently supports pytest.');await BeastIDERuntime.startDebug({adapter:'debugpy',configuration:{name:`BEAST pytest · ${selectedNode||state.selectedFile||'suite'}`,type:'python',request:'launch',module:'pytest',args:selectedNode?[selectedNode]:state.selectedFile?[state.selectedFile]:[],cwd:activeRoot(),console:'internalConsole',justMyCode:true}});await BeastRouter.navigate('compatibility');return;}state.loading=true;render();try{const result=await window.beastDesktop.runWorkspaceTest({...scope(),id,...(state.selectedFile?{file:state.selectedFile}:{}),...(selectedNode?{node:selectedNode}:{})});state.result={...result,at:Date.now()};history.unshift(state.result);BeastStore.addLedger(`Test ${result.ok?'passed':'failed'}: ${result.file||id} · ${result.receipt?.id||''}`);}finally{state.loading=false;render();}}
    async function loadAgentVerification(){const runId=String(state.agentRunId||'').trim();if(!runId)throw new Error('Enter a durable AgentRun ID.');state.verificationLoading=true;state.verificationError='';render();try{const params=new URLSearchParams({root_path:activeRoot(),category:state.verificationCategory,status:state.verificationStatus,query:state.verificationQuery});const result=await BeastRuntime.request(`/edgek/agent-runs/${encodeURIComponent(runId)}/console/verification?${params.toString()}`,{method:'GET',timeoutMs:30000});state.verification=result?.verification_console||result;BeastStore.addLedger(`Verification console loaded for ${runId} · ${state.verification?.summary?.total_checks||0} check(s)`);}catch(error){state.verification=null;state.verificationError=String(error.message||error);}finally{state.verificationLoading=false;render();}}
    root.addEventListener('change',event=>{if(event.target.matches('[data-test-root]')){state.rootId=event.target.value;discover();}if(event.target.matches('[data-test-target]'))state.selectedTarget=event.target.value;if(event.target.matches('[data-test-node]'))state.selectedNode=event.target.value;if(event.target.matches('[data-agent-verification-category]'))state.verificationCategory=event.target.value;if(event.target.matches('[data-agent-verification-status]'))state.verificationStatus=event.target.value;render();});root.addEventListener('input',event=>{if(event.target.matches('[data-agent-verification-run]'))state.agentRunId=event.target.value;if(event.target.matches('[data-agent-verification-query]'))state.verificationQuery=event.target.value;});root.addEventListener('click',event=>{const file=event.target.closest('[data-test-file]');if(file){state.selectedFile=file.dataset.testFile;state.selectedNode=state.nodes.find(item=>item.path===state.selectedFile)?.id||'';render();return;}const failure=event.target.closest('[data-test-failure-path]');if(failure){BeastEditorCortex.openFile(failure.dataset.testFailurePath).then(()=>{BeastRouter.navigate('workspace');BeastEditorCortex.gotoLine(Number(failure.dataset.testFailureLine)||1);});return;}const action=event.target.closest('[data-test-action]')?.dataset.testAction;if(action==='discover')discover();if(action==='run')run(false).catch(error=>{state.error=String(error.message||error);render();});if(action==='debug')run(true).catch(error=>{state.error=String(error.message||error);render();});if(action==='open'&&state.selectedFile)BeastEditorCortex.openFile(state.selectedFile).then(()=>BeastRouter.navigate('workspace'));if(action==='load-agent-verification')loadAgentVerification().catch(error=>{state.verificationError=String(error.message||error);render();});});queueMicrotask(discover);return {node:root,dispose(){disposed=true;}};}
  window.BeastTestingPage={renderer};
})();
